  .top-note {
    display: inline-flex; align-items: center; gap: 8px;
    padding: 9px 13px; border: 1px solid rgba(21, 27, 46, .08);
    border-radius: 999px; color: var(--muted); font-size: 12.5px;
    background: rgba(255, 255, 255, .65); backdrop-filter: blur(8px);
  }
  .dot-live { width: 7px; height: 7px; border-radius: 50%; background: #2f9e6e; box-shadow: 0 0 0 4px rgba(47, 158, 110, .13); }

  .view { animation: viewIn .35s ease both; }
  @keyframes viewIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }

  .test-head { text-align: center; max-width: 780px; margin: 0 auto 22px; }
  .eyebrow {
    display: inline-flex; align-items: center; gap: 8px;
