      ghost.style.left = rect.left + "px";
      ghost.style.top = rect.top + "px";
      ghost.style.width = rect.width + "px";
      ghost.style.height = rect.height + "px";
      document.body.appendChild(ghost);
      li.classList.add("is-dragging");
      document.body.classList.add("is-dragging-active");
      activeDrag = { li, ul };
      started = true;
    }

    ev.preventDefault();
    const dx = ev.clientX - startX;
    const dy = ev.clientY - startY;
    const tilt = Math.max(-1.8, Math.min(1.8, dx * 0.018));
    ghost.style.transform = `translate(${dx}px, ${dy}px) rotate(${tilt}deg)`;

    const under = document.elementFromPoint(ev.clientX, ev.clientY);
    const target = under && under.closest ? under.closest(".disc-item") : null;
    if (target && target !== li && target.parentElement === ul && !target.classList.contains("drag-ghost")) {
      const r = target.getBoundingClientRect();
      const before = ev.clientY < r.top + r.height / 2;
      if (before) {
        if (li.nextElementSibling !== target) ul.insertBefore(li, target);
      } else {
        if (li.previousElementSibling !== target) ul.insertBefore(li, target.nextElementSibling);
      }
      updateRanks(ul);
    }

    const margin = 84;
    if (ev.clientY < margin) {
      window.scrollBy(0, -14);
    } else if (ev.clientY > window.innerHeight - margin) {
      window.scrollBy(0, 14);
    }
  };

  const finish = (ev) => {
    if (ev.pointerId !== pointerId) return;
    document.removeEventListener("pointermove", onMove);
    document.removeEventListener("pointerup", finish);
    document.removeEventListener("pointercancel", finish);
    if (!started) return;
    if (ghost) ghost.remove();
    li.classList.remove("is-dragging");
    document.body.classList.remove("is-dragging-active");
    activeDrag = null;
    updateRanks(ul);
  };

  document.addEventListener("pointermove", onMove, { passive: false });
  document.addEventListener("pointerup", finish);
  document.addEventListener("pointercancel", finish);
}

function setupSortable(ul) {
  updateRanks(ul);

  ul.addEventListener("pointerdown", (e) => {
    const li = e.target.closest(".disc-item");
    if (!li || li.parentElement !== ul) return;
    if (e.pointerType === "mouse" && e.button !== 0) return;
    if (e.pointerType !== "mouse" && !e.target.closest(".drag-handle")) return;
    beginPointerDrag(e, li, ul);
  });

  ul.addEventListener("keydown", (e) => {
    const li = e.target.closest(".disc-item");
    if (!li || li.parentElement !== ul) return;
    if (e.key === "ArrowUp") {
      e.preventDefault();
      moveWithKeyboard(li, ul, -1);
    } else if (e.key === "ArrowDown") {
      e.preventDefault();
      moveWithKeyboard(li, ul, 1);
    } else if (e.key === "Home") {
      e.preventDefault();
      ul.insertBefore(li, ul.firstElementChild);
      updateRanks(ul);
      li.focus({ preventScroll: true });
    } else if (e.key === "End") {
      e.preventDefault();
      ul.appendChild(li);
      updateRanks(ul);
      li.focus({ preventScroll: true });
    }
  });
}

function buildTest() {
  tabsEl.replaceChildren();
  stepsEl.replaceChildren();

  STEP_NAMES.forEach((name, i) => {
    const tab = document.createElement("button");
    tab.type = "button";
    tab.className = "tab";
    tab.id = "tab-" + i;
    tab.setAttribute("role", "tab");
    tab.setAttribute("aria-controls", "step-" + i);
    tab.dataset.step = String(i);
    const num = document.createElement("span");
    num.className = "tab-num";
    num.textContent = String(i + 1);
    const label = document.createElement("span");
    label.className = "tab-label";
    label.textContent = name;
    tab.append(num, label);
    tab.addEventListener("click", () => setStep(i));
    tabsEl.appendChild(tab);
  });

  for (let s = 0; s < 8; s++) {
    const pane = document.createElement("section");
    pane.className = "step-pane";
    pane.id = "step-" + s;
    pane.setAttribute("role", "tabpanel");
    pane.setAttribute("aria-labelledby", "tab-" + s);
    pane.hidden = s !== 0;

    const grid = document.createElement("div");
    grid.className = "grid3";

    for (let j = 0; j < 3; j++) {
      const listIndex = s * 3 + j;
      const list = DATA[listIndex];
      const card = document.createElement("article");
      card.className = "card";

      const head = document.createElement("div");
      head.className = "card-head";
      const kicker = document.createElement("span");
      kicker.className = "card-kicker";
      kicker.textContent = "Я наиболее";
      const index = document.createElement("span");
      index.className = "card-index";
      index.textContent = String(listIndex + 1).padStart(2, "0");
      head.append(kicker, index);

      const ul = document.createElement("ul");
      ul.className = "disc-list";
      ul.dataset.list = String(listIndex);
      ul.setAttribute("role", "list");
      ul.setAttribute("aria-label", `Группа ${listIndex + 1}: ранжирование высказываний`);

      list.forEach(([text, type]) => {
        const li = document.createElement("li");
        li.className = "disc-item";
        li.dataset.type = type;
        li.tabIndex = 0;
        li.setAttribute("role", "listitem");

        const handle = document.createElement("span");
        handle.className = "drag-handle";
        handle.setAttribute("aria-hidden", "true");
        handle.title = "Перетащите, чтобы изменить порядок";
        handle.innerHTML = handleSvg;

        const textEl = document.createElement("span");
        textEl.className = "item-text";
        textEl.textContent = text;

        const rank = document.createElement("span");
        rank.className = "item-rank";
        rank.setAttribute("aria-hidden", "true");

        li.append(handle, textEl, rank);
        ul.appendChild(li);
      });

      const foot = document.createElement("div");
      foot.className = "card-foot";
      foot.textContent = "Я наименее";

      card.append(head, ul, foot);
      grid.appendChild(card);
      setupSortable(ul);
    }

    pane.appendChild(grid);
    stepsEl.appendChild(pane);
  }
}

function render() {
  Array.from(tabsEl.children).forEach((tab, i) => {
    const active = i === step;
    tab.classList.toggle("is-active", active);
    tab.classList.toggle("is-done", i < step && !active);
    tab.setAttribute("aria-selected", active ? "true" : "false");
    tab.tabIndex = active ? 0 : -1;
  });

  Array.from(stepsEl.children).forEach((pane, i) => {
    pane.hidden = i !== step;
  });

  prevBtn.disabled = step === 0;
  nextBtn.hidden = step === 7;
  finishBtn.hidden = step !== 7;
  stepCountEl.textContent = `Шаг ${step + 1} из 8`;
  progressBar.style.width = `${((step + 1) / 8) * 100}%`;

  const activeTab = tabsEl.children[step];
  if (activeTab && activeTab.scrollIntoView) {
    activeTab.scrollIntoView({ block: "nearest", inline: "center", behavior: "smooth" });
  }
}

function setStep(n) {
  step = Math.max(0, Math.min(7, n));
  render();
}

function calculateScores() {
  const totals = { d: 0, i: 0, s: 0, c: 0 };
  document.querySelectorAll(".disc-list").forEach((ul) => {
    const items = Array.from(ul.querySelectorAll(".disc-item"));
    if (items.length < 2) return;
    const mostType = items[0].dataset.type;
    const leastType = items[items.length - 1].dataset.type;
    if (mostType in totals) totals[mostType] += 1;
    if (leastType in totals) totals[leastType] -= 1;
  });
  return totals;
}

function showResult() {
  const score = calculateScores();
  scoreLine.textContent = `D:${score.d}, I:${score.i}, S:${score.s}, C:${score.c}`;

  const maxAbs = Math.max(4, ...TYPE_ORDER.map((key) => Math.abs(score[key])));
  scoreGrid.replaceChildren();

  TYPE_ORDER.forEach((key) => {
    const value = score[key];
    const meta = TYPE_META[key];
    const card = document.createElement("article");
    card.className = "score-card";
    card.dataset.type = key;

    const top = document.createElement("div");
    top.className = "score-top";
    const letter = document.createElement("span");
    letter.className = "score-letter";
    letter.textContent = meta.letter;
    const val = document.createElement("span");
    val.className = "score-value";
    val.textContent = value > 0 ? "+" + value : String(value);
    top.append(letter, val);

    const name = document.createElement("div");
    name.className = "score-name";
    name.textContent = meta.name;

    const axis = document.createElement("div");
    axis.className = "score-axis";
    const fill = document.createElement("div");
    fill.className = "score-fill";
    const ratio = Math.abs(value) / maxAbs;
    if (value >= 0) {
      fill.style.left = "50%";
      fill.style.width = `${ratio * 50}%`;
    } else {
      fill.style.left = `${50 - ratio * 50}%`;
      fill.style.width = `${ratio * 50}%`;
    }
    axis.appendChild(fill);

    const scale = document.createElement("div");
    scale.className = "score-scale";
    scale.innerHTML = `<span>−${maxAbs}</span><span>0</span><span>+${maxAbs}</span>`;

    card.append(top, name, axis, scale);
    scoreGrid.appendChild(card);
  });

  testView.hidden = true;
  resultView.hidden = false;
  window.scrollTo({ top: 0, behavior: "smooth" });
}

function restartTest() {
  buildTest();
  step = 0;
  render();
  resultView.hidden = true;
  testView.hidden = false;
  window.scrollTo({ top: 0, behavior: "smooth" });
}

prevBtn.addEventListener("click", () => setStep(step - 1));
nextBtn.addEventListener("click", () => setStep(step + 1));
finishBtn.addEventListener("click", showResult);
restartBtn.addEventListener("click", restartTest);

tabsEl.addEventListener("keydown", (e) => {
  if (e.key !== "ArrowLeft" && e.key !== "ArrowRight") return;
  const dir = e.key === "ArrowRight" ? 1 : -1;
  const next = Math.max(0, Math.min(7, step + dir));
  e.preventDefault();
  setStep(next);
  tabsEl.children[next].focus();
});

buildTest();
render();
