async function main(){
  const tabs=await (await fetch('http://127.0.0.1:9333/json')).json();
  const page=tabs.find(t=>t.type==='page'&&t.url.includes('index.html'));
  const ws=new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((res,rej)=>{ws.onopen=res;ws.onerror=rej;});
  let id=0; const pending=new Map(); const reqs=[]; const errors=[];
  ws.onmessage=(ev)=>{const m=JSON.parse(ev.data); if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id);} if(m.method==='Network.requestWillBeSent') reqs.push(m.params.request.url); if(m.method==='Runtime.exceptionThrown') errors.push(m.params.exceptionDetails.text);};
  const send=(method,params={})=>new Promise(res=>{const i=++id;pending.set(i,res);ws.send(JSON.stringify({id:i,method,params}));});
  await send('Network.enable'); await send('Runtime.enable'); await send('Page.enable');
  await send('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:1,mobile:true});
  await send('Page.reload',{ignoreCache:true});
  await new Promise(r=>setTimeout(r,1200));
  const r=await send('Runtime.evaluate',{expression:`(()=>{for(let i=0;i<7;i++)document.getElementById('nextBtn').click();document.getElementById('finishBtn').click();return document.getElementById('scoreLine').textContent;})()`,returnByValue:true});
  console.log('score',r.result.result.value);
  console.log('requests',reqs);
  console.log('exceptions',errors);
  ws.close();
}
main().catch(e=>{console.error(e);process.exit(1);});
